<?php
namespace App\Policies;
use App\Models\{ProjectPlannedUnit,User}; use App\Policies\Concerns\CompanyOwnedPolicy;
class ProjectPlannedUnitPolicy { use CompanyOwnedPolicy; public function viewAny(User $u):bool{return $this->canForResource($u,'view_any_project_planned_unit');} public function view(User $u,ProjectPlannedUnit $r):bool{return $this->canForRecord($u,'view_project_planned_unit',$r);} public function create(User $u):bool{return $this->canForResource($u,'create_project_planned_unit');} public function update(User $u,ProjectPlannedUnit $r):bool{return $this->canForRecord($u,'update_project_planned_unit',$r);} public function delete(User $u,ProjectPlannedUnit $r):bool{return $r->status==='planned'&&$this->canForRecord($u,'delete_project_planned_unit',$r);} public function approvePlannedUnit(User $u,ProjectPlannedUnit $r):bool{return $this->canForRecord($u,'approve_planned_unit',$r);} public function cancelPlannedUnit(User $u,ProjectPlannedUnit $r):bool{return $this->canForRecord($u,'cancel_planned_unit',$r);} }
